for (int i = 0; i < 4; i++) { 
n *= 16; 
char c = e[i]; 
if (isdigit(c)) { 
n += c - '0'; 
} else if (c >= 'a' && c <= 'f') { 
n += c - 'a' + 10; 
} else if (c >= 'A' && c <= 'F') { 
n += c - 'A' + 10; 
} else { 
unexpected(c); 
} 
} 
sv.push_back(n); 
} 
break; 
default: 
unexpected(ch); 
} 
} else { 
sv.push_back(ch); 
} 
} 
} 
