private static byte[] avroEncoded(byte[] bytes) { 
assert bytes.length < 64; 
byte[] result = new byte[1 + bytes.length]; 
result[0] = (byte) (bytes.length * 2); // zig-zag encoding 
System.arraycopy(bytes, 0, result, 1, bytes.length); 
return result; 
} 
